namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public class RecipeCategory
{
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public string Icon { get; set; } = string.Empty;
}

using RecipeCommunity.Models;

namespace RecipeCommunity.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private readonly List<RecipeCategory> _categories;

    public RecipeService()
    {
        _categories = new List<RecipeCategory>
        {
            new() { Name = "Breakfast", Description = "Start your day right with these morning favorites", Icon = "🥞" },
            new() { Name = "Lunch", Description = "Quick and satisfying midday meals", Icon = "🥗" },
            new() { Name = "Dinner", Description = "Hearty dishes for the whole family", Icon = "🍝" },
            new() { Name = "Desserts", Description = "Sweet treats to end any meal", Icon = "🍰" },
            new() { Name = "Snacks", Description = "Light bites for any time of day", Icon = "🍿" },
            new() { Name = "Drinks", Description = "Refreshing beverages and cocktails", Icon = "🥤" }
        };

        _recipes = new List<Recipe>
        {
            new() { Id = 1, Title = "Classic Pancakes", Category = "Breakfast", Ingredients = "2 cups flour\n2 eggs\n1.5 cups milk\n2 tbsp sugar\n1 tsp baking powder\nPinch of salt", Steps = "1. Mix dry ingredients in a bowl.\n2. Whisk eggs and milk together.\n3. Combine wet and dry ingredients until just mixed.\n4. Heat a griddle over medium heat.\n5. Pour batter and cook until bubbles form, then flip.\n6. Serve with maple syrup and butter.", AverageRating = 4.5, RatingCount = 12 },
            new() { Id = 2, Title = "Caesar Salad", Category = "Lunch", Ingredients = "1 head romaine lettuce\n1/2 cup croutons\n1/4 cup parmesan cheese\nCaesar dressing\nBlack pepper", Steps = "1. Wash and chop the romaine lettuce.\n2. Toss with Caesar dressing.\n3. Add croutons and shaved parmesan.\n4. Season with freshly cracked black pepper.\n5. Serve immediately.", AverageRating = 4.2, RatingCount = 8 },
            new() { Id = 3, Title = "Spaghetti Bolognese", Category = "Dinner", Ingredients = "400g spaghetti\n500g ground beef\n1 can crushed tomatoes\n1 onion, diced\n3 cloves garlic\n2 tbsp olive oil\nSalt and pepper\nFresh basil", Steps = "1. Cook spaghetti according to package directions.\n2. Sauté onion and garlic in olive oil.\n3. Add ground beef and cook until browned.\n4. Pour in crushed tomatoes and simmer 20 minutes.\n5. Season with salt, pepper, and basil.\n6. Serve sauce over spaghetti.", AverageRating = 4.8, RatingCount = 24 },
            new() { Id = 4, Title = "Chocolate Brownies", Category = "Desserts", Ingredients = "1 cup butter\n2 cups sugar\n4 eggs\n1 cup cocoa powder\n1 cup flour\n1 tsp vanilla\n1/2 tsp salt", Steps = "1. Preheat oven to 350°F (175°C).\n2. Melt butter and mix with sugar.\n3. Beat in eggs one at a time.\n4. Stir in cocoa, flour, vanilla, and salt.\n5. Pour into greased 9x13 pan.\n6. Bake 25-30 minutes.\n7. Cool before cutting.", AverageRating = 4.9, RatingCount = 31 },
            new() { Id = 5, Title = "Trail Mix Energy Bites", Category = "Snacks", Ingredients = "1 cup oats\n1/2 cup peanut butter\n1/3 cup honey\n1/2 cup chocolate chips\n1/4 cup dried cranberries\n1/4 cup sunflower seeds", Steps = "1. Mix all ingredients in a large bowl.\n2. Refrigerate for 30 minutes.\n3. Roll into 1-inch balls.\n4. Store in an airtight container in the fridge.", AverageRating = 4.3, RatingCount = 15 },
            new() { Id = 6, Title = "Mango Smoothie", Category = "Drinks", Ingredients = "1 cup frozen mango\n1 banana\n1 cup yogurt\n1/2 cup orange juice\n1 tbsp honey", Steps = "1. Add all ingredients to a blender.\n2. Blend until smooth.\n3. Pour into a glass and serve immediately.", AverageRating = 4.6, RatingCount = 19 }
        };
    }

    public List<RecipeCategory> GetCategories() => _categories;

    public List<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipeById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public List<Recipe> GetAllRecipes() => _recipes;

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(recipe);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is not null && stars >= 1 && stars <= 5)
        {
            var totalStars = recipe.AverageRating * recipe.RatingCount;
            recipe.RatingCount++;
            recipe.AverageRating = Math.Round((totalStars + stars) / recipe.RatingCount, 1);
        }
    }
}

@rendermode InteractiveServer
@using RecipeCommunity.Services
@inject RecipeService RecipeService

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= _hoveredStar ? "hovered" : "") @(star <= _selectedStar ? "selected" : "")"
              @onmouseover="() => OnHover(star)"
              @onmouseout="OnMouseOut"
              @onclick="() => OnClick(star)"
              role="button"
              aria-label="@star stars">
            @(star <= (_hoveredStar > 0 ? _hoveredStar : _selectedStar) ? "★" : "☆")
        </span>
    }
    @if (_submitted)
    {
        <span class="rating-feedback ms-2 text-success">Thanks for rating!</span>
    }
</div>
<div class="rating-info text-muted small mt-1">
    Average: @AverageRating.ToString("F1") / 5 (@RatingCount ratings)
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double AverageRating { get; set; }
    [Parameter] public int RatingCount { get; set; }

    private int _hoveredStar;
    private int _selectedStar;
    private bool _submitted;

    private void OnHover(int star) => _hoveredStar = star;
    private void OnMouseOut() => _hoveredStar = 0;

    private void OnClick(int star)
    {
        _selectedStar = star;
        _submitted = true;
        RecipeService.AddRating(RecipeId, star);
        var recipe = RecipeService.GetRecipeById(RecipeId);
        if (recipe is not null)
        {
            AverageRating = recipe.AverageRating;
            RatingCount = recipe.RatingCount;
        }
    }
}

@page "/recipe/{Id:int}"
@using RecipeCommunity.Models
@using RecipeCommunity.Services
@inject RecipeService RecipeService

<PageTitle>@(recipe?.Title ?? "Recipe") - Recipe Community</PageTitle>

@if (recipe is null)
{
    <h3>Recipe not found</h3>
    <p><a href="/">Return to Home</a></p>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="/recipes/@recipe.Category.ToLower()">@recipe.Category</a></li>
            <li class="breadcrumb-item active">@recipe.Title</li>
        </ol>
    </nav>

    <h2>@recipe.Title</h2>
    <span class="badge bg-secondary mb-3">@recipe.Category</span>

    <div class="mb-4">
        <StarRating RecipeId="@recipe.Id" AverageRating="@recipe.AverageRating" RatingCount="@recipe.RatingCount" />
    </div>

    <div class="row">
        <div class="col-md-4">
            <div class="card mb-3">
                <div class="card-header"><strong>Ingredients</strong></div>
                <div class="card-body">
                    <ul class="list-unstyled mb-0">
                        @foreach (var ingredient in recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                        {
                            <li>• @ingredient</li>
                        }
                    </ul>
                </div>
            </div>
        </div>
        <div class="col-md-8">
            <div class="card">
                <div class="card-header"><strong>Steps</strong></div>
                <div class="card-body">
                    @foreach (var step in recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                    {
                        <p>@step</p>
                    }
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter] public int Id { get; set; }
    private Recipe? recipe;

    protected override void OnInitialized()
    {
        recipe = RecipeService.GetRecipeById(Id);
    }
}

@page "/recipes/{CategoryName}"
@using RecipeCommunity.Models
@using RecipeCommunity.Services
@inject RecipeService RecipeService

<PageTitle>@CategoryName Recipes - Recipe Community</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">@CategoryName</li>
    </ol>
</nav>

<h2>@CategoryName Recipes</h2>

@if (recipes.Count == 0)
{
    <p class="text-muted">No recipes in this category yet. <a href="/submit">Submit one!</a></p>
}
else
{
    <div class="row">
        @foreach (var recipe in recipes)
        {
            <div class="col-md-6 col-lg-4 mb-4">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text text-muted small">
                            ★ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)
                        </p>
                    </div>
                    <div class="card-footer">
                        <a href="/recipe/@recipe.Id" class="btn btn-outline-primary btn-sm">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;
    private List<Recipe> recipes = new();

    protected override void OnInitialized()
    {
        recipes = RecipeService.GetRecipesByCategory(CategoryName);
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeCommunity.Models
@using RecipeCommunity.Services
@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe - Recipe Community</PageTitle>

<h2>Submit a Recipe</h2>
<p class="text-muted">Share your favorite recipe with the community!</p>

@if (_submitted)
{
    <div class="alert alert-success">
        <strong>Recipe submitted!</strong> Your recipe has been added to the community.
        <a href="/recipe/@_newRecipeId">View it here</a>.
    </div>
}
else
{
    <EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" class="form-control" @bind-Value="_model.Title" placeholder="e.g., Grandma's Apple Pie" />
            <ValidationMessage For="() => _model.Title" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" class="form-select" @bind-Value="_model.Category">
                <option value="">-- Select a category --</option>
                @foreach (var cat in RecipeService.GetCategories())
                {
                    <option value="@cat.Name">@cat.Name</option>
                }
            </InputSelect>
            <ValidationMessage For="() => _model.Category" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients</label>
            <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="_model.Ingredients" placeholder="Enter each ingredient on a new line" />
            <ValidationMessage For="() => _model.Ingredients" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps</label>
            <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="_model.Steps" placeholder="Enter each step on a new line" />
            <ValidationMessage For="() => _model.Steps" class="text-danger" />
        </div>

        <button type="submit" class="btn btn-primary">Submit Recipe</button>
    </EditForm>
}

@code {
    private RecipeFormModel _model = new();
    private bool _submitted;
    private int _newRecipeId;

    private void HandleSubmit()
    {
        var recipe = new Recipe
        {
            Title = _model.Title,
            Category = _model.Category,
            Ingredients = _model.Ingredients,
            Steps = _model.Steps
        };
        RecipeService.AddRecipe(recipe);
        _newRecipeId = recipe.Id;
        _submitted = true;
    }

    private class RecipeFormModel
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Title is required")]
        public string Title { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Category is required")]
        public string Category { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Ingredients are required")]
        public string Ingredients { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Steps are required")]
        public string Steps { get; set; } = string.Empty;
    }
}

