using RecipeCommunity.Models;

namespace RecipeCommunity.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private readonly List<RecipeCategory> _categories;

    public RecipeService()
    {
        _categories = new List<RecipeCategory>
        {
            new() { Name = "Breakfast", Description = "Start your day right with these morning favorites", Icon = "🥞" },
            new() { Name = "Lunch", Description = "Quick and satisfying midday meals", Icon = "🥗" },
            new() { Name = "Dinner", Description = "Hearty dishes for the whole family", Icon = "🍝" },
            new() { Name = "Desserts", Description = "Sweet treats to end any meal", Icon = "🍰" },
            new() { Name = "Snacks", Description = "Light bites for any time of day", Icon = "🍿" },
            new() { Name = "Drinks", Description = "Refreshing beverages and cocktails", Icon = "🥤" }
        };

        _recipes = new List<Recipe>
        {
            new() { Id = 1, Title = "Classic Pancakes", Category = "Breakfast", Ingredients = "2 cups flour\n2 eggs\n1.5 cups milk\n2 tbsp sugar\n1 tsp baking powder\nPinch of salt", Steps = "1. Mix dry ingredients in a bowl.\n2. Whisk eggs and milk together.\n3. Combine wet and dry ingredients until just mixed.\n4. Heat a griddle over medium heat.\n5. Pour batter and cook until bubbles form, then flip.\n6. Serve with maple syrup and butter.", AverageRating = 4.5, RatingCount = 12 },
            new() { Id = 2, Title = "Caesar Salad", Category = "Lunch", Ingredients = "1 head romaine lettuce\n1/2 cup croutons\n1/4 cup parmesan cheese\nCaesar dressing\nBlack pepper", Steps = "1. Wash and chop the romaine lettuce.\n2. Toss with Caesar dressing.\n3. Add croutons and shaved parmesan.\n4. Season with freshly cracked black pepper.\n5. Serve immediately.", AverageRating = 4.2, RatingCount = 8 },
            new() { Id = 3, Title = "Spaghetti Bolognese", Category = "Dinner", Ingredients = "400g spaghetti\n500g ground beef\n1 can crushed tomatoes\n1 onion, diced\n3 cloves garlic\n2 tbsp olive oil\nSalt and pepper\nFresh basil", Steps = "1. Cook spaghetti according to package directions.\n2. Sauté onion and garlic in olive oil.\n3. Add ground beef and cook until browned.\n4. Pour in crushed tomatoes and simmer 20 minutes.\n5. Season with salt, pepper, and basil.\n6. Serve sauce over spaghetti.", AverageRating = 4.8, RatingCount = 24 },
            new() { Id = 4, Title = "Chocolate Brownies", Category = "Desserts", Ingredients = "1 cup butter\n2 cups sugar\n4 eggs\n1 cup cocoa powder\n1 cup flour\n1 tsp vanilla\n1/2 tsp salt", Steps = "1. Preheat oven to 350°F (175°C).\n2. Melt butter and mix with sugar.\n3. Beat in eggs one at a time.\n4. Stir in cocoa, flour, vanilla, and salt.\n5. Pour into greased 9x13 pan.\n6. Bake 25-30 minutes.\n7. Cool before cutting.", AverageRating = 4.9, RatingCount = 31 },
            new() { Id = 5, Title = "Trail Mix Energy Bites", Category = "Snacks", Ingredients = "1 cup oats\n1/2 cup peanut butter\n1/3 cup honey\n1/2 cup chocolate chips\n1/4 cup dried cranberries\n1/4 cup sunflower seeds", Steps = "1. Mix all ingredients in a large bowl.\n2. Refrigerate for 30 minutes.\n3. Roll into 1-inch balls.\n4. Store in an airtight container in the fridge.", AverageRating = 4.3, RatingCount = 15 },
            new() { Id = 6, Title = "Mango Smoothie", Category = "Drinks", Ingredients = "1 cup frozen mango\n1 banana\n1 cup yogurt\n1/2 cup orange juice\n1 tbsp honey", Steps = "1. Add all ingredients to a blender.\n2. Blend until smooth.\n3. Pour into a glass and serve immediately.", AverageRating = 4.6, RatingCount = 19 }
        };
    }

    public List<RecipeCategory> GetCategories() => _categories;

    public List<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipeById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public List<Recipe> GetAllRecipes() => _recipes;

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(recipe);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is not null && stars >= 1 && stars <= 5)
        {
            var totalStars = recipe.AverageRating * recipe.RatingCount;
            recipe.RatingCount++;
            recipe.AverageRating = Math.Round((totalStars + stars) / recipe.RatingCount, 1);
        }
    }
}

